negativeExample:
import java.io.IOException;

class ProcessMonitorThread {
    public void killThread() { /* ... */ }
}

public class MyProcess {
    private ProcessMonitorThread fMonitor; // Not final

    public MyProcess() {
        this.fMonitor = null; // Can be null
    }

    public void terminate() throws IOException {
        // Should not match as fMonitor is not final and could be null
        if (fMonitor != null) {
            fMonitor.killThread();
        }
    }
}
